@dataclass
class Style:
    hide: bool = False
    bold: bool = False
    faint: bool = False
    italic: bool = False
    underline: bool = False
    blinkSlow: bool = False
    blinkRapid: bool = False
    inverse: bool = False
    conceal: bool = False
    crossOut: bool = False
    frame: bool = False
    encircle: bool = False
    overline: bool = False
