    passStyle: Style = field(default_factory=lambda: Style(foreground="green"))
    failStyle: Style = field(default_factory=lambda: Style(bold=True, foreground="red"))
    skipStyle: Style = field(default_factory=lambda: Style(foreground="lightBlack"))
    fileStyle: Style = field(default_factory=lambda: Style(foreground="cyan"))
    lineStyle: Style = field(default_factory=lambda: Style(foreground="magenta"))
    passPackageStyle: Style = field(default_factory=lambda: Style(foreground="green", hide=True))
    failPackageStyle: Style = field(default_factory=lambda: Style(bold=True, foreground="red", hide=True))
    coverThreshold: float = 50.0
    coveredStyle: Style = field(default_factory=lambda: Style(foreground="green"))
    uncoveredStyle: Style = field(default_factory=lambda: Style(bold=True, foreground="yellow"))
    removals: List[str] = field(default_factory=list)
    leaveTestPrefix: bool = False

    def copy(self) -> 'Config':
        c = Config()
        c.labelType = self.labelType
        for key in STYLE_KEYS:
            setattr(c, key, getattr(self, key).copy())
        c.coverThreshold = self.coverThreshold
        c.removals = list(self.removals)
        c.leaveTestPrefix = self.leaveTestPrefix
        return c

class ConfigError(Exception):
    pass


def color_escape(value: str, background: bool = False) -> str:
    val = value.strip()
    if val in COLOR_CODES:
        code = COLOR_CODES[val]
        if background:
            if 30 <= code <= 37:
                code += 10
            elif 90 <= code <= 97:
                code += 10
        return f"\033[{code}m"
    m = re.fullmatch(r"#([0-9a-fA-F]{6})", val)
    if m:
        hx = m.group(1)
        r, g, b = int(hx[0:2], 16), int(hx[2:4], 16), int(hx[4:6], 16)
        return f"\033[{48 if background else 38};2;{r};{g};{b}m"
    m = re.fullmatch(r"rgb\(\s*([^,]+)\s*,\s*([^,]+)\s*,\s*([^,]+)\s*\)", val)
    if m:
        comps = []
        for part in m.groups():
            p = part.strip()
            try:
                if p.lower().startswith("0x"):
                    n = int(p, 16)
                else:
                    n = int(p, 10)
            except ValueError:
                raise ConfigError("invalid format")
            if n < 0 or n > 256:
                raise ConfigError("invalid format")
            comps.append(n)
        return f"\033[{48 if background else 38};2;{comps[0]};{comps[1]};{comps[2]}m"
    raise ConfigError("invalid format")


def strip_comment(line: str) -> str:
    in_single = False
    in_double = False
    escaped = False
    for i, ch in enumerate(line):
        if escaped:
            escaped = False
            continue
        if ch == "\\" and in_double:
            escaped = True
            continue
        if ch == "'" and not in_double:
            in_single = not in_single
            continue
        if ch == '"' and not in_single:
            in_double = not in_double
            continue
        if ch == "#" and not in_single and not in_double:
            # YAML comments begin at # when it is the first non-space char or follows space.
            if i == 0 or line[i-1].isspace():
                return line[:i]
    return line


def unquote_value(raw: str) -> str:
    s = raw.strip()
    if len(s) >= 2 and ((s[0] == s[-1] == '"') or (s[0] == s[-1] == "'")):
        s = s[1:-1]
        if raw.strip().startswith('"'):
            # A small subset of YAML double-quoted escapes; enough for usual regex strings.
            s = s.replace('\\n', '\n').replace('\\t', '\t').replace('\\"', '"').replace('\\\\', '\\')
    return s


def parse_bool(s: str) -> bool:
    v = unquote_value(s)
    if v == "true":
        return True
    if v == "false":
        return False
    raise ConfigError("invalid format")


def split_key_value(s: str) -> Tuple[str, str]:
    if ":" not in s:
        raise ConfigError("invalid format")
    k, v = s.split(":", 1)
    return k.strip(), v.strip()


def apply_config_file(base: Config, path: str) -> Config:
    # Parse into a copy first; the original program effectively ignores a file that fails to unmarshal.
    cfg = base.copy()
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()
    except OSError as e:
        raise ConfigError(str(e))

    i = 0
    while i < len(lines):
        raw = lines[i].rstrip("\n\r")
        no_comment = strip_comment(raw).rstrip()
        i += 1
        if not no_comment.strip():
            continue
        indent = len(no_comment) - len(no_comment.lstrip(" "))
        if indent != 0:
            continue
        key, val = split_key_value(no_comment)
        if key in STYLE_KEYS:
            style = getattr(cfg, key).copy()
            # Inline empty mapping is ignored; nested properties follow.
            while i < len(lines):
                nxt_raw = lines[i].rstrip("\n\r")
                nxt = strip_comment(nxt_raw).rstrip()
                if not nxt.strip():
                    i += 1
                    continue
                nindent = len(nxt) - len(nxt.lstrip(" "))
                if nindent == 0:
                    break
                prop_line = nxt.strip()
                pkey, pval = split_key_value(prop_line)
                if pkey in BOOL_KEYS:
                    setattr(style, pkey, parse_bool(pval))
                elif pkey == "foreground":
                    style.foreground = unquote_value(pval)
                    if style.foreground:
                        color_escape(style.foreground, False)
                elif pkey == "background":
                    style.background = unquote_value(pval)
                    if style.background:
                        color_escape(style.background, True)
                else:
                    # Unknown YAML fields are tolerated by many YAML decoders; ignore them.
                    pass
                i += 1
            setattr(cfg, key, style)
        elif key == "labelType":
            cfg.labelType = unquote_value(val)
        elif key == "coverThreshold":
            try:
                cfg.coverThreshold = float(unquote_value(val))
            except ValueError:
                raise ConfigError("invalid format")
        elif key == "leaveTestPrefix":
            cfg.leaveTestPrefix = parse_bool(val)
        elif key == "removals":
            removals: List[str] = []
            # If inline [] appears, leave empty. Otherwise parse list items.
            while i < len(lines):
                nxt_raw = lines[i].rstrip("\n\r")
                nxt = strip_comment(nxt_raw).rstrip()
                if not nxt.strip():
                    i += 1
                    continue
                nindent = len(nxt) - len(nxt.lstrip(" "))
                if nindent == 0:
                    break
                item = nxt.strip()
                if item.startswith("-"):
                    removals.append(unquote_value(item[1:].strip()))
                i += 1
            cfg.removals = removals
        else:
            # Ignore unknown top-level keys.
            pass
    return cfg


def log_config_error(path: str, err: str = "invalid format") -> None:
    now = datetime.datetime.now().strftime("%Y/%m/%d %H:%M:%S")
    print(f"{now} error unmarshaling yaml from {path} :  {err}", file=sys.stderr)


def go_env_value(name: str) -> str:
    env_val = os.environ.get(name)
    if env_val:
        return env_val
    go = shutil.which("go")
    if not go:
        return ""
    try:
        r = subprocess.run([go, "env", name], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False)
        if r.returncode == 0:
            return r.stdout.decode("utf-8", "replace").strip()
    except Exception:
        pass
    return ""


def config_paths() -> List[str]:
    dirs: List[str] = [os.getcwd()]
    if os.environ.get("RICHGO_LOCAL") != "1":
        gp = go_env_value("GOPATH")
        gr = go_env_value("GOROOT")
        home = os.environ.get("HOME", os.path.expanduser("~"))
        dirs.extend([gp, gr, home])
    names = [".richstyle", ".richstyle.yaml", ".richstyle.yml"]
    paths: List[str] = []
    for d in dirs:
        if not d:
            continue
        for n in names:
            paths.append(os.path.join(d, n))
    return paths


def load_config() -> Config:
    cfg = Config()
    for path in config_paths():
        if os.path.exists(path):
            try:
                cfg = apply_config_file(cfg, path)
            except ConfigError as e:
                # The observed binary logs invalid color/YAML errors and continues with prior config.
                msg = str(e) if str(e) else "invalid format"
                if msg != "invalid format":
                    # Most unmarshal validation failures render as exactly "invalid format".
                    msg = "invalid format"
                log_config_error(path, msg)
    return cfg


def label_for(kind: str, cfg: Config) -> str:
    lt = cfg.labelType
    if lt == "long":
        if kind == "":
            lab = "     "
        else:
            lab = kind.ljust(5)[:5]
        return lab + "| "
    if lt == "short":
        mp = {"BUILD": "!!", "START": ">", "PASS": "o", "FAIL": "x", "SKIP": "-", "COVER": "%", "": ""}
        sym = mp.get(kind, "")
        return sym.ljust(2) + " "
    # Invalid label types behave like none.
    return ""


def test_text(raw: str, cfg: Config) -> str:
    # Indentation is based on subtest nesting in the original test name.
    name_part = raw.split(None, 1)[0] if raw.split(None, 1) else raw
    depth = name_part.count("/")
    shown = raw
    if not cfg.leaveTestPrefix and shown.startswith("Test"):
        shown = shown[4:]
    return "  " * depth + shown


FILE_RE = re.compile(r"^(.*?)([^:\s]*\.go)(:\d+(?::\d+)?)(.*)$")
COVER_RE = re.compile(r"^coverage: (\d+\.\d)% of statements$")
OK_RE = re.compile(r"^ok\s+(\S+)(?:\s+\S+)?(?:\s+(coverage: \d+\.\d% of statements))?$")
Q_RE = re.compile(r"^\?\s+(.+\[no test files\])$")
FAIL_SUMMARY_RE = re.compile(r"^FAIL(\s+.*)$")

class Formatter:
    def __init__(self, cfg: Config, writer: BinaryIO):
        self.cfg = cfg
        self.writer = writer
        self.current = Style()
        self.removals = [re.compile(p) for p in cfg.removals]

    def write_s(self, s: str) -> None:
        self.writer.write(s.encode("utf-8", "replace"))

    def flush(self) -> None:
        try:
            self.writer.flush()
        except Exception:
            pass

    def render_plain_styled(self, text: str, style: Style) -> None:
        if style.hide:
            return
        pre = style.prefix()
        if pre:
            self.write_s(pre + text + RESET + "\n")
        else:
            self.write_s(text + "\n")

    def render(self, kind: str, text: str, style: Style, build_special: bool = False) -> None:
        if style.hide:
            return
        pre = style.prefix()
        label = label_for(kind, self.cfg)
        if build_special:
            # The original build header writes the reset after the newline.
            if pre:
                self.write_s(pre + label + text + "\n" + RESET)
            else:
                self.write_s(label + text + "\n")
            return
        if pre:
            self.write_s(pre + label + text + RESET + "\n")
        else:
            self.write_s(label + text + "\n")

    def render_unmatched(self, line: str) -> None:
        style = self.current
        if style.hide:
            return
        m = FILE_RE.match(line)
        if not m:
            self.render("", line, style)
            return
        prefix_text, file_text, loc_text, rest = m.groups()
        main_pre = style.prefix()
        file_pre = self.cfg.fileStyle.prefix()
        line_pre = self.cfg.lineStyle.prefix()
        out = []
        if main_pre:
            out.append(main_pre)
        out.append(label_for("", self.cfg))
        out.append(prefix_text)
        if file_pre:
            out.append(file_pre)
            out.append(file_text)
            out.append(RESET)
        else:
            out.append(file_text)
        if line_pre:
            out.append(line_pre)
            out.append(loc_text)
            out.append(RESET)
        else:
            out.append(loc_text)
        if main_pre:
            out.append(main_pre)
        out.append(rest)
        if main_pre:
            out.append(RESET)
        out.append("\n")
        self.write_s("".join(out))

    def removed(self, line: str) -> bool:
        for r in self.removals:
            if r.search(line):
                return True
        return False

    def handle_line(self, line: str) -> None:
        # Scanner-like behavior: empty lines are ignored in formatted mode.
        if line == "":
            return
        if self.removed(line):
            return

        if line.startswith("=== RUN   Test"):
            self.current = self.cfg.startStyle
            raw = line[len("=== RUN   "):]
            self.render("START", test_text(raw, self.cfg), self.cfg.startStyle)
            return

        for prefix, kind, style in (
            ("--- PASS: Test", "PASS", self.cfg.passStyle),
            ("--- FAIL: Test", "FAIL", self.cfg.failStyle),
            ("--- SKIP: Test", "SKIP", self.cfg.skipStyle),
        ):
            if line.startswith(prefix):
                self.current = style
                raw = line[len(prefix) - 4:]  # keep the leading "Test" in the raw name/suffix
                # Explanation: prefix includes "Test"; stripping up to after ': ' is simpler.
                raw = line.split(": ", 1)[1]
                self.render(kind, test_text(raw, self.cfg), style)
                return

        stripped = line.strip()
        if line.startswith("PASS") and stripped == "PASS":
            self.current = self.cfg.passPackageStyle
            self.render_plain_styled("PASS", self.cfg.passPackageStyle)
            return
        if line.startswith("FAIL") and stripped == "FAIL":
            self.current = self.cfg.failPackageStyle
            self.render_plain_styled("FAIL", self.cfg.failPackageStyle)
            return

        m = OK_RE.match(line)
        if m:
            pkg, cov = m.group(1), m.group(2)
            self.current = self.cfg.passStyle
            text = pkg + (" " + cov if cov else " ")
            self.render("PASS", text, self.cfg.passStyle)
            return

        m = Q_RE.match(line)
        if m:
            self.current = self.cfg.skipStyle
            self.render("SKIP", m.group(1), self.cfg.skipStyle)
            return

        m = FAIL_SUMMARY_RE.match(line)
        if m:
            self.current = self.cfg.failStyle
            self.render("FAIL", m.group(1), self.cfg.failStyle)
            return

        m = COVER_RE.match(line)
        if m:
            pct_s = m.group(1)
            pct = float(pct_s)
            hashes = int(pct // 10)
            if hashes < 0:
                hashes = 0
            if hashes > 10:
                hashes = 10
            bar = "#" * hashes + "_" * (10 - hashes)
            style = self.cfg.coveredStyle if pct >= self.cfg.coverThreshold else self.cfg.uncoveredStyle
            self.render("COVER", f"{pct_s}% [{bar}]", style)
            # Coverage does not change the current style in the observed behavior.
            return

        if line.startswith("# "):
            self.current = self.cfg.buildStyle
            self.render("BUILD", line[2:], self.cfg.buildStyle, build_special=True)
            return

        self.render_unmatched(line)

    def feed_bytes(self, data: bytes) -> None:
        # Go's bufio.Scanner splits on \n and drops a trailing \r if present? bufio.ScanLines
        # removes \r before \n, so mimic that.
        text = data.decode("utf-8", "replace")
        # splitlines handles final unterminated line and CRLF; unlike str.split('\n'), it won't
        # produce an extra token for a trailing newline, matching Scanner.
        for line in text.splitlines():
            if line.endswith("\r"):
                line = line[:-1]
            self.handle_line(line)
        self.flush()


def testfilter_command() -> int:
    cfg = load_config()
    if not sys.stdout.isatty():
        data = sys.stdin.buffer.read()
        if data:
            sys.stdout.buffer.write(data)
        sys.stdout.buffer.write(b"\n")
        sys.stdout.buffer.flush()
        try:
            sys.stderr.buffer.write(b"\n")
            sys.stderr.buffer.flush()
        except Exception:
            pass
        return 0
    data = sys.stdin.buffer.read()
    fmt = Formatter(cfg, sys.stdout.buffer)
    fmt.feed_bytes(data)
    return 0


def run_go(args: List[str]) -> int:
    try:
        proc = subprocess.run(["go"] + args)
        return proc.returncode
    except FileNotFoundError:
        print("go: command not found", file=sys.stderr)
        return 127


def run_test(args: List[str]) -> int:
    # Formatted output is only used when stdout is a terminal; otherwise the command is mostly
    # pipeline-friendly, with the same success-time blank line quirk as the observed tool.
    try:
        proc = subprocess.run(["go", "test"] + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except FileNotFoundError:
        print("go: command not found", file=sys.stderr)
        return 127

    if not sys.stdout.isatty():
        if proc.stdout:
            sys.stdout.buffer.write(proc.stdout)
        if proc.stderr:
            sys.stderr.buffer.write(proc.stderr)
        if proc.returncode == 0:
            sys.stdout.buffer.write(b"\n")
            try:
                sys.stderr.buffer.write(b"\n")
            except Exception:
                pass
        sys.stdout.buffer.flush()
        sys.stderr.buffer.flush()
        return proc.returncode

    cfg = load_config()
    out_fmt = Formatter(cfg, sys.stdout.buffer)
    err_fmt = Formatter(cfg, sys.stderr.buffer)
    if proc.stdout:
        out_fmt.feed_bytes(proc.stdout)
    if proc.stderr:
        err_fmt.feed_bytes(proc.stderr)
    return proc.returncode


def main(argv: List[str]) -> int:
    if argv and argv[0] == "testfilter":
        return testfilter_command()
    if argv and argv[0] == "test":
        return run_test(argv[1:])
    return run_go(argv)

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
